import com.google.common.hash.BloomFilter;
import com.google.common.hash.Funnels;

public class UserService {
    private final BloomFilter<Long> userBloomFilter;
    private final UserRepository userRepository;
    private final RedisTemplate<String, User> redisTemplate;

    public UserService(UserRepository userRepository, RedisTemplate<String, User> redisTemplate) {
        this.userRepository = userRepository;
        this.redisTemplate = redisTemplate;
        // Initialize Bloom filter expecting 1,000,000 elements with a 0.01 false positive rate
        this.userBloomFilter = BloomFilter.create(
            Funnels.longFunnel(), 
            1_000_000, 
            0.01
        );
        loadValidIdsIntoFilter();
    }

    private void loadValidIdsIntoFilter() {
        userRepository.findAllIds().forEach(userBloomFilter::put);
    }

    public User findUser(Long userId) {
        // 1. Perimeter defense via Bloom Filter
        if (!userBloomFilter.mightContain(userId)) {
            return null; // Definitively does not exist, short-circuit immediately
        }

        // 2. Check Cache Layer
        String cacheKey = "user:" + userId;
        User user = redisTemplate.opsForValue().get(cacheKey);
        if (user != null) {
            return user;
        }

        // 3. Fallback to Database
        user = userRepository.findById(userId).orElse(null);
        if (user != null) {
            redisTemplate.opsForValue().set(cacheKey, user, Duration.ofMinutes(10));
        } else {
            // Prevent penetration by caching a null/empty sentinel with a short TTL
            redisTemplate.opsForValue().set(cacheKey, User.NULL_OBJECT, Duration.ofMinutes(1));
        }
        return user;
    }
}
